-- Módulo Receituário: insumos, fichas técnicas e operacionais, ingredientes e a
-- configuração do preço sugerido. Os dados vêm da planilha FICHA TÉCNICA E
-- RECEITUÁRIO da casa (scripts/gerar-importacao-receituario.ts).


-- CreateEnum
CREATE TYPE "TipoFicha" AS ENUM ('PRONTA', 'PRE_PREPARO');

-- CreateTable
CREATE TABLE "receituario_insumos" (
    "id" SERIAL NOT NULL,
    "codigo" VARCHAR(20) NOT NULL,
    "nome" VARCHAR(120) NOT NULL,
    "categoria" VARCHAR(60),
    "unidadeUso" VARCHAR(5) NOT NULL,
    "produtoId" INTEGER,
    "unidadeCompra" VARCHAR(20),
    "precoCompra" DECIMAL(12,4),
    "qtdPorUnidade" DECIMAL(12,4) NOT NULL DEFAULT 1,
    "rendimento" DECIMAL(5,4) NOT NULL DEFAULT 1,
    "estimado" BOOLEAN NOT NULL DEFAULT false,
    "observacao" TEXT,
    "ativo" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "receituario_insumos_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "receituario_fichas" (
    "id" SERIAL NOT NULL,
    "codigo" VARCHAR(20) NOT NULL,
    "nome" VARCHAR(120) NOT NULL,
    "categoria" VARCHAR(40) NOT NULL,
    "tipo" "TipoFicha" NOT NULL DEFAULT 'PRONTA',
    "operacoes" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "porcoes" INTEGER NOT NULL DEFAULT 1,
    "rendimentoTotal" DECIMAL(12,2),
    "unidadeRendimento" VARCHAR(5) NOT NULL DEFAULT 'g',
    "tempoPreparo" VARCHAR(40),
    "passos" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "observacoes" TEXT,
    "alergenicos" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "viabilidade" VARCHAR(40),
    "modoForno" VARCHAR(60),
    "temperatura" VARCHAR(30),
    "umidade" VARCHAR(30),
    "tempoForno" VARCHAR(40),
    "sonda" VARCHAR(20),
    "ajusteForno" TEXT,
    "utensilios" TEXT,
    "pontoDeControle" TEXT,
    "armazenamento" TEXT,
    "montagem" TEXT,
    "custoManualPorcao" DECIMAL(12,4),
    "conferida" BOOLEAN NOT NULL DEFAULT false,
    "ativo" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "receituario_fichas_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "receituario_ingredientes" (
    "id" SERIAL NOT NULL,
    "fichaId" INTEGER NOT NULL,
    "ordem" INTEGER NOT NULL DEFAULT 0,
    "insumoId" INTEGER,
    "subFichaId" INTEGER,
    "nomeLivre" VARCHAR(120),
    "quantidade" DECIMAL(12,3) NOT NULL,
    "unidade" VARCHAR(5),
    "preparo" VARCHAR(160),

    CONSTRAINT "receituario_ingredientes_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "receituario_config" (
    "id" INTEGER NOT NULL DEFAULT 1,
    "metaFoodCost" DECIMAL(5,4) NOT NULL DEFAULT 0.30,
    "markup" DECIMAL(6,3) NOT NULL DEFAULT 3,

    CONSTRAINT "receituario_config_pkey" PRIMARY KEY ("id")
