CREATE INDEX "receituario_ingredientes_fichaId_idx" ON "receituario_ingredientes"("fichaId");

-- CreateIndex
CREATE INDEX "receituario_ingredientes_insumoId_idx" ON "receituario_ingredientes"("insumoId");

