ALTER TABLE "receituario_insumos" ADD CONSTRAINT "receituario_insumos_produtoId_fkey" FOREIGN KEY ("produtoId") REFERENCES "products"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "receituario_ingredientes" ADD CONSTRAINT "receituario_ingredientes_fichaId_fkey" FOREIGN KEY ("fichaId") REFERENCES "receituario_fichas"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "receituario_ingredientes" ADD CONSTRAINT "receituario_ingredientes_insumoId_fkey" FOREIGN KEY ("insumoId") REFERENCES "receituario_insumos"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

