  ('INS-413', 'Uva roxa', 'Frutas', 'g', NULL, 'kg', 13.08::DECIMAL, 1000::DECIMAL, 0.95::DECIMAL, true, '[PREMISSA] preço estimado com base na uva Itália (verde); confirmar com nota fiscal.'),
  ('INS-414', 'Alface romana', 'Vegetais', 'g', NULL, 'kg', 7.5::DECIMAL, 1000::DECIMAL, 1::DECIMAL, true, '[PREMISSA] preço estimado com base na alface americana; confirmar com nota fiscal.'),
