-- As fichas dos pratos do buffet ganham a operação Buffet.
UPDATE "receituario_fichas" f SET "operacoes" = array_append(f."operacoes", 'BUFFET')
WHERE EXISTS (SELECT 1 FROM "buffet_pratos" p WHERE p."codFicha" = f."codigo") AND NOT ('BUFFET' = ANY(f."operacoes"));
